import Foundation

protocol UserRepository {
    func fetchUser() -> String
}

struct MockUserRepo: UserRepository {
    func fetchUser() -> String {
        return "MockUser"
    }
}

final class UserProfile {
    private let repo: UserRepository

    init(repo: UserRepository) {
        self.repo = repo
    }

    func userHeading() -> String {
        return "User: \(repo.fetchUser())"
    }
}

let profile = UserProfile(repo: MockUserRepo())
print(profile.userHeading())

import Foundation

protocol PaymentGateway {
    func pay(cents: Int) -> Bool
}

final class SpyPaymentGateway: PaymentGateway {
    var wasCalled = false
    var lastCents = 0

    func pay(cents: Int) -> Bool {
        wasCalled = true
        lastCents = cents
        return true
    }
}

let spy = SpyPaymentGateway()
_ = spy.pay(cents: 2500)
print("Spy called: \(spy.wasCalled), Cents: \(spy.lastCents)")
